const e="darling-downs-eisteddfod",d=2026,t="Read from the 2026 syllabus (text, whole document). The syllabus prints the association's bank BSB and account number; they are not copied, only the payment methods are kept. No competition dates or session times are printed, only the entry window. The syllabus prints 'Championships $21.00' as a fee but lists no championship section; the fee is kept as printed. The time-limit rule 'Dsections have a limit of 5minutes' is quoted as printed because it is ambiguous.",o={Title:"Rules & Criteria",Subtitle:"Darling Downs Eisteddfod 2026 dance syllabus at the Millmerran Cultural Centre.",NoticeTitle:"Please Read Before Registering",Notice:"Entries open {{EntriesOpen}} and close {{EntriesClose}}. Entry is through Comps-Online only, and entries are accepted only once payment is received. Strictly no late entries.",Notes:["Age is counted on {{AgeDate}}.","Dance sections have no event dates in the syllabus; programmes are emailed."],Sections:[{Key:"general",Title:"Rules and Conditions",Items:["All sessions are held at {{Venue}}.","All material must be age appropriate.","The committee is not responsible for errors or omissions on entry forms, or in the syllabus or programme. Competitors should check the programme against their entry form when they receive it.","The committee may amend or refuse any entry, combine or cancel a section with too few entries, or split a section with too many entries.","The committee may change the date or venue if it considers it necessary, and has full control of the programme at all times.","Failure to comply with the rules may involve disqualification and the withholding of prizes.","The decision of the committee in all questions and disputes not provided for in the rules is final. All entries are received subject to this rule and are not subject to appeal at law."]},{Key:"eligibility",Title:"Eligibility and Entries",Items:["The age of an entrant is counted on {{AgeDate}}.","In duo, trio and group sections the age class is set by the oldest member as at {{AgeDate}}.","Open sections are open to performers of any age, who must be of open standard.","Entries in all categories except Open sections must carry the correct date of birth of the entrant; entries without it are not accepted.","Strictly one entry per competitor per section.","A competitor may enter a duo or trio event with different partners; the maximum number of times an individual can enter the same duo or trio section is 2.","Each competitor pays the competitor pass ({{CompetitorPassFee}}). Duo and trio partners also pay their own competitor pass. Group days and all other spectators have a separate entry fee."]},{Key:"registration",Title:"How To Enter",Items:["All entries must be lodged through Comps-Online.","Entries open {{EntriesOpen}} and close {{EntriesClose}}. Entries are accepted only once payment is received. Strictly no late entries.","Fees can be paid by PayPal or direct deposit, quoting the Comps-Online invoice number as the reference.","Strictly no refunds. Entries are not refunded if an entrant withdraws.","Programmes are emailed."]},{Key:"fees",Title:"Entry Fees",Items:["{{Fees}}.","Competitor pass: {{CompetitorPassFee}}.","Admission: {{Admission}}.","Protest fee: {{ProtestFee}}."]},{Key:"venue",Title:"Venue",Items:["{{Venue}}."]},{Key:"dates",Title:"Dates",Items:["Entries open {{EntriesOpen}}; entries close {{EntriesClose}}. The syllabus prints no session dates."]},{Key:"conduct",Title:"Performance and Conduct",Items:["Entrants must be withdrawn by the teacher or parent of the entrant; withdrawals from other parties are not accepted.","Entrants must tell the secretary or backstage official at the earliest convenience, or at the start of the relevant session, if they are withdrawing from a section.","The secretary or backstage official withdraws entrants who are not in the marshalling area 10 minutes before their performance.","All entrants must mark themselves present with the backstage official at the start of the relevant session and be side stage at least 10 minutes before their section.","Appropriate attire must be worn, including dance tights and shoes relevant to the genre of dance.","Inappropriate behaviour side stage and on stage is not tolerated.","Prompting is strictly not permitted in any section. Anyone prompting from the audience or side stage is removed from the auditorium or backstage area.","No person is permitted on stage except for prop placement. Only the backstage official or announcer, the music player and committee members are allowed side stage during performances.","Taps must not be worn in any part of the auditorium except on the stage.","Competitors must use the dressing areas provided and not change in the auditorium or passageways.","All entrants must dance in the order of the program.","Music must be submitted through music uploads. Keep a backup copy on a device. All music is to be pre-cut, mixed or faded.","Audience: no flash cameras during performances; mobile phones and devices off or on silent; no entering or leaving the auditorium during a performance; no excessive noise; do not speak with a competitor who is performing; keep young children under control.","Photography and video: you may only video or photograph your own child, from the designated table. Anyone taking photos or videos of other performers elsewhere is asked to delete them and is escorted from the building. The committee may have an official photographer and members of the media may take photos; tell the secretary if you do not want your photograph taken."]},{Key:"judging",Title:"Adjudication and Time Limits",Items:["Solo sections have a time limit of 3 minutes unless otherwise specified. The syllabus also prints 'Dsections have a limit of 5minutes'. Adjudicators may stop a performance if the time limit is exceeded.","The adjudicator may disqualify or penalise an entrant for inappropriate or offensive attire, behaviour, prompting and material choice.","The adjudicator may withhold prizes according to merit, and the adjudicator's decision is final unless an error in identity occurs.","In any improvisation section all material is the choice of the adjudicator.","Adjudicator reports are made available as music uploads at the end of each day.","No routine in any section other than Acro may have more than 4 tricks. Any move where the hips go over the head counts as a trick (walkovers, round offs, aerials, baranis, handsprings, chin stand and similar), and each element counts. Going over the limit means disqualification from placing in that routine. Cartwheels, shoulder rolls, leg mounts and well executed knee drops are not tricks. A routine in the Acro section must still be dance based. Ask the committee, by Facebook or email, about tricks not listed.","In dance sections, vocal backing is not permitted in the vocal section of any Song and Dance item. Newer backing tracks with fragments of added harmonisation are acceptable."]},{Key:"complaints",Title:"Protests",Items:["Protests, appeals and complaints must be lodged in writing with the committee within 30 minutes of the end of the relevant section, with a fee of {{ProtestFee}}.","Appeals can include, but are not limited to, alleged competitor number mistakes, errors in calculating marks, competitor ineligibility and interpretation of rules."]},{Key:"prizes",Title:"Prizes",Items:["Unless stated otherwise: a medallion for 1st, 2nd and 3rd in solo, duo and trio sections; Very Highly Commended and Highly Commended certificates in solo, duo and trio sections; a plaque for 1st and certificates for other placings in group sections.","Choreographers Challenge, junior and senior: the winner receives a BDF weekend pass and a $50 dancewear voucher.","Trophies awarded by the adjudicator: Accomplished Female Dancer (junior and senior); Distinguished Male Dancer (junior and senior); Excellence in Classical, Jazz, Tap, Lyrical / Slow Modern, Contemporary, Hip-Hop and Acro; Excellence in Dance for 6 and under, 8 and under, 10 and under, 12 and under, 14 and under, 16 and under and Open age categories; Passion for Dance; Effective Group Dynamics Shield; Charlotte Taylor Performance Award (a memorable solo performance).","Awards chosen by the committee: Spirit of Dance Trophy (junior and senior), Most Entertaining Group, Most Outstanding Presentation and Attire Group Trophy, Courage and Bravery Award (a solo performer who was courageous in taking the stage), Most Outstanding Presentation and Attire Solo/Duo/Trio, Founding Members Award.","Champion Dance School Shield: awarded to the dance studio with the highest number of points in any 6 group dances across all age groups.","Madeleine Trueman Sportsmanship Award: voted by the competitors for another competitor who showed true sportsmanship, supported peers, tried their hardest and respected the discipline of dance.","No prize is awarded unless there is sufficient merit. The adjudicator may withhold any prize."]}],Documents:[{Title:"Darling Downs Eisteddfod 2026 Syllabus (PDF)",Url:"https://darlingdownseisteddfod.org/wp-content/uploads/2026/01/DDE-Syllabus-2026.pdf"}]},n=[],a=[],i=[{Title:"Improvisation Slow Solo",Source:"2026 Syllabus Dance rules 5-7, 9",Sections:{About:null,TimeAndFormat:null,Rules:["Marshal side stage at least one section before the improvisation; entrants are disqualified if not present when called or if the section has started before they marshal.","Improvisation attire: plain class leotard, no bling or sequins; plain coloured shorts or skirts are the competitor's choice. A competitor in the wrong outfit has one chance to change in the toilets while waiting, and must change alone.","Entrants in a solo improvisation may choose the genre of dance when they hear the music chosen by the adjudicator.","No parents, teachers, friends or others except committee members or improvisation marshals may approach or interact with improvisation competitors once the music starts; failure to comply means disqualification."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Marshal side stage at least one section before the improvisation; entrants are disqualified if not present when called or if the section has started before they marshal.
- Improvisation attire: plain class leotard, no bling or sequins; plain coloured shorts or skirts are the competitor's choice. A competitor in the wrong outfit has one chance to change in the toilets while waiting, and must change alone.
- Entrants in a solo improvisation may choose the genre of dance when they hear the music chosen by the adjudicator.
- No parents, teachers, friends or others except committee members or improvisation marshals may approach or interact with improvisation competitors once the music starts; failure to comply means disqualification.`},{Title:"Improvisation Fast Solo",Source:"2026 Syllabus Dance rules 5-7, 9",Sections:{About:null,TimeAndFormat:null,Rules:["Marshal side stage at least one section before the improvisation; entrants are disqualified if not present when called or if the section has started before they marshal.","Improvisation attire: plain class leotard, no bling or sequins; plain coloured shorts or skirts are the competitor's choice. A competitor in the wrong outfit has one chance to change in the toilets while waiting, and must change alone.","Entrants in a solo improvisation may choose the genre of dance when they hear the music chosen by the adjudicator.","No parents, teachers, friends or others except committee members or improvisation marshals may approach or interact with improvisation competitors once the music starts; failure to comply means disqualification."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Marshal side stage at least one section before the improvisation; entrants are disqualified if not present when called or if the section has started before they marshal.
- Improvisation attire: plain class leotard, no bling or sequins; plain coloured shorts or skirts are the competitor's choice. A competitor in the wrong outfit has one chance to change in the toilets while waiting, and must change alone.
- Entrants in a solo improvisation may choose the genre of dance when they hear the music chosen by the adjudicator.
- No parents, teachers, friends or others except committee members or improvisation marshals may approach or interact with improvisation competitors once the music starts; failure to comply means disqualification.`},{Title:"Improvisation Group (Minimum 4 Competitors)",Source:"2026 Syllabus Dance rule 8",Sections:{About:null,TimeAndFormat:null,Rules:["Each group must have at least 4 competitors. Only group members may be present during the time given to choreograph their own steps. The genre is the group's choice after receiving the music selected by the adjudicator.","Music is received at the end of one session and improvisation performances begin in the next session. Space is allocated for each group to choreograph. The group provides its own means of playing the music; it is airdropped or emailed.","Junior group improvisation entries must have one teacher or student teacher present when the music is received, and are allocated another group to time keep for; this person is for counting only.","Group improvisations take place on the groups days. Groups need not be school based and students may enter with whomever they please."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Each group must have at least 4 competitors. Only group members may be present during the time given to choreograph their own steps. The genre is the group's choice after receiving the music selected by the adjudicator.
- Music is received at the end of one session and improvisation performances begin in the next session. Space is allocated for each group to choreograph. The group provides its own means of playing the music; it is airdropped or emailed.
- Junior group improvisation entries must have one teacher or student teacher present when the music is received, and are allocated another group to time keep for; this person is for counting only.
- Group improvisations take place on the groups days. Groups need not be school based and students may enter with whomever they please.`},{Title:"Adjudicators Combo",Source:"2026 Syllabus Dance rule 10",Sections:{About:null,TimeAndFormat:null,Rules:["The combo is in Jazz, Lyrical / Slow Modern or Contemporary. After the fees are lodged, the entrant receives the combo when the programme is released. If the section does not run, the entry fee for it is refunded. Attire is as for improvisation."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- The combo is in Jazz, Lyrical / Slow Modern or Contemporary. After the fees are lodged, the entrant receives the combo when the programme is released. If the section does not run, the entry fee for it is refunded. Attire is as for improvisation.`},{Title:"Choreographers Challenge",Source:"2026 Syllabus Dance rule 11",Sections:{About:null,TimeAndFormat:null,Rules:["Entrants must compete in the adjudicators combo, student choreography and the improvisation section.","Entrants must also choreograph one routine to be entered for another solo, duo, trio or group. The entrant cannot be in this routine. The routine may have costuming and may be a repeat of a piece from another section.","Entry fee: Choreographers Challenge $13.00."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Entrants must compete in the adjudicators combo, student choreography and the improvisation section.
- Entrants must also choreograph one routine to be entered for another solo, duo, trio or group. The entrant cannot be in this routine. The routine may have costuming and may be a repeat of a piece from another section.
- Entry fee: Choreographers Challenge $13.00.`},{Title:"Student Choreography Solo",Source:"2026 Syllabus Dance rule 15",Sections:{About:null,TimeAndFormat:null,Rules:["Must be fully the student's own work. The entrant chooses their own music and style of dance. The costume must suit the dance."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Must be fully the student's own work. The entrant chooses their own music and style of dance. The costume must suit the dance.`},{Title:"Acro Solo",Source:"2026 Syllabus Dance rule 12",Sections:{About:null,TimeAndFormat:null,Rules:["A routine in the Acro section must still be dance based. The 4-trick limit that applies to other sections does not apply here."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- A routine in the Acro section must still be dance based. The 4-trick limit that applies to other sections does not apply here.`}],s=[],r=[{Key:"EntriesOpen",Kind:"date",Label:"Entries open",Value:"2026-01-05 at 9am",Source:"2026 Syllabus Entry Fees page"},{Key:"EntriesClose",Kind:"date",Label:"Entries close",Value:"2026-02-15 at midnight",Source:"2026 Syllabus Entry Fees page"},{Key:"AgeDate",Kind:"date",Label:"Date on which each entrant's age is counted",Value:"2026-01-01",Source:"2026 Syllabus Rules and Conditions, Age"},{Key:"Venue",Kind:"address",Label:"Venue for all sessions",Value:{Name:"Millmerran Cultural Centre",Address:"Walpole Street",City:"Millmerran, QLD",MapUrl:"",Directions:""},Source:"2026 Syllabus Location and Contact"},{Key:"Contact",Kind:"contact",Label:"Eisteddfod contact",Value:{Name:"Darling Downs Eisteddfod",Role:"Questions, permissible acro tricks, withdrawals",Phone:"",WhatsApp:"",Email:"ddeisteddfod@gmail.com"},Source:"2026 Syllabus Location and Contact"},{Key:"Website",Kind:"link",Label:"Website",Value:"https://darlingdownseisteddfod.org",Source:"2026 Syllabus Location and Contact"},{Key:"SocialMedia",Kind:"link",Label:"Social media",Value:"Facebook: Darling Downs Eisteddfod. Instagram: Darling_downs_eisteddfod",Source:"2026 Syllabus Location and Contact"},{Key:"Fees",Kind:"fee",Label:"Entry fees",Value:"Solos $13.00; Duo/Trio $17.00; Championships $21.00; Choreographers Challenge $13.00; Groups $21.00",Source:"2026 Syllabus Entry Fees"},{Key:"CompetitorPassFee",Kind:"fee",Label:"Competitor pass",Value:"$15, paid with the entry fees; includes a free email program and free entry for the competitor only",Source:"2026 Syllabus Entry Forms, rule 8"},{Key:"ProtestFee",Kind:"fee",Label:"Protest fee",Value:"$25",Source:"2026 Syllabus Protests"},{Key:"Admission",Kind:"fee",Label:"Admission prices",Value:"Session $7 per person; Day Pass $20 per person; Season Pass $60 per person; under 5 years gold coin. Pre-purchase on the website or buy at the door",Source:"2026 Syllabus Admission"},{Key:"Notices",Kind:"news",Label:"Notices printed in the syllabus",Value:[{Date:"2026-01-05",Title:"Entries open",Text:"Entries open Monday 5 January 2026 at 9am. Entry is through Comps-Online only. Programmes are emailed.",Url:""},{Date:"2026-02-15",Title:"Entries close",Text:"Entries close Sunday 15 February 2026 at midnight. Strictly no late entries.",Url:""}],Source:"2026 Syllabus Entry Fees page"}],l=[{Claim:"Rules and conditions, fees, awards and section rules were read from the eisteddfod's own 2026 syllabus.",SourceType:"Primary - the event's own rules document",Source:"2026 Syllabus",Url:"https://darlingdownseisteddfod.org/wp-content/uploads/2026/01/DDE-Syllabus-2026.pdf"}],c={TemplateKey:e,Year:2026,Note:t,Page:o,ParticipantTypes:n,AgeGroups:a,Competitions:i,CompetitionAgeGroups:s,Variables:r,Evidence:l};export{a as AgeGroups,s as CompetitionAgeGroups,i as Competitions,l as Evidence,t as Note,o as Page,n as ParticipantTypes,e as TemplateKey,r as Variables,d as Year,c as default};
